import java.util.Scanner;

public class Main {
    static long target_value;
    static int min_steps = Integer.MAX_VALUE;

    static void process(long val, int cost) {
        if (cost >= min_steps) return;
        if (val == 0) {
            min_steps = cost;
            return;
        }
        long s = 1, c = 1;
        while (s * 10 + 1 <= val) {
            s = s * 10 + 1;
            c++;
        }
        process(val % s, cost + c * (int) (val / s));
        process(s * 10 + 1 - val, cost + 1 + (int) c);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        target_value = scanner.nextLong();
        process(target_value, 0);
        System.out.println(min_steps);
        scanner.close();
    }
}
